1	import { SCENE_TRANSITION_VEIL_SEQUENCE } from "../config/transition.config.js";
2	import { sceneTransitionVeil } from "../core/setup.js";
3	import { Aria } from "../utils/Aria.js";
4	import { Helpers } from "../utils/Helpers.js";
5	import { SceneTransitionRuntime } from "./SceneTransitionRuntime.js";
6	import type {
7	  DomVisibilityState,
8	  PageSceneRuntimePolicy,
9	  SceneSyncState,
10	  SceneActiveState,
11	  SceneDomTargetKey,
12	  SceneOverlayPolicy,
13	  ScenePolicyRuntimeOptions,
14	  SceneVeilPolicy,
15	  SceneVisibilityPolicy,
16	} from "../types/runtime.types.js";
17	import type {
18	  SceneProgressTransitionWindow,
19	  TransitionEaseKey,
20	  TransitionVeilRuntimePort,
21	} from "../types/object-runtime.types.js";
22	
23	export class ScenePolicyRuntime {
24	  private readonly _globalDomTargetCache = new Map<string, HTMLElement | null>();
25	  private readonly _scopedDomTargetCache = new WeakMap<
26	    ParentNode,
27	    Map<string, HTMLElement | null>
28	  >();
29	
30	  constructor(
31	    private readonly _sceneTransitionRuntime: SceneTransitionRuntime,
32	  ) {}
33	
34	  syncScene<TSceneKey extends string, TSheetId extends string>(
35	    state: SceneSyncState<TSceneKey, TSheetId>,
36	    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
37	  ): void {
38	    this._syncSceneUiState(
39	      state.sceneKey,
40	      state.sheetId,
41	      options.engine,
42	      options.isTheatreAuthorMode,
43	      options.sceneSheetEffectRuntime,
44	    );
45	    this._syncVisibilityPolicies(state, options);
46	    options.backgroundController?.sync(
47	      state.sceneKey,
48	      state.progress,
49	      state.sheetId,
50	      options.backgroundPolicy ?? null,
51	    );
52	    this._syncVeilPolicies(state, options);
53	  }
54	
55	  resetPolicies<TSceneKey extends string, TSheetId extends string>(
56	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId> | undefined,
57	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
58	    root?: ParentNode | null,
59	  ): void {
60	    if (!policies) return;
61	    this._resetSceneOverlayPolicies(policies, root);
62	    this._resetSceneVeilPolicies(policies, resolveTransitionVeil);
63	  }
64	
65	  private _syncSceneUiState<TSceneKey extends string, TSheetId extends string>(
66	    sceneKey: TSceneKey,
67	    sheetId: TSheetId | null,
68	    engine: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>["engine"],
69	    isTheatreAuthorMode: boolean,
70	    sceneSheetEffectRuntime: ScenePolicyRuntimeOptions<
71	      TSceneKey,
72	      TSheetId
73	    >["sceneSheetEffectRuntime"],
74	  ): void {
75	    if (isTheatreAuthorMode) return;
76	    sceneSheetEffectRuntime.sync(engine?.getScene() ?? null, sceneKey, sheetId);
77	  }
78	
79	  private _syncVisibilityPolicies<
80	    TSceneKey extends string,
81	    TSheetId extends string,
82	  >(
83	    state: { sceneKey: TSceneKey; progress: number; sheetId: TSheetId | null },
84	    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
85	  ): void {
86	    const policies = options.pageRuntimePolicies;
87	    if (!policies) return;
88	    this._syncSceneVisibilityPolicies(
89	      state.sceneKey,
90	      state.sheetId,
91	      policies,
92	      options.root,
93	    );
94	    this._syncSceneOverlayPolicies(
95	      state.sceneKey,
96	      state.progress,
97	      state.sheetId,
98	      policies,
99	      options.isTheatreAuthorMode,
100	      options.root,
101	    );
102	  }
103	
104	  private _syncVeilPolicies<
105	    TSceneKey extends string,
106	    TSheetId extends string,
107	  >(
108	    state: { sceneKey: TSceneKey; progress: number; sheetId: TSheetId | null },
109	    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
110	  ): void {
111	    const policies = options.pageRuntimePolicies;
112	    if (!policies) return;
113	    if (options.skipVeilPolicies) return;
114	    if (options.isTheatreAuthorMode) {
115	      this._resetSceneVeilPolicies(policies, options.resolveTransitionVeil);
116	      return;
117	    }
118	    this._syncSceneVeilPolicies(
119	      state.sceneKey,
120	      state.progress,
121	      state.sheetId,
122	      policies,
123	      options.resolveTransitionVeil,
124	    );
125	  }
126	
127	  private _syncSceneOverlayPolicies<
128	    TSceneKey extends string,
129	    TSheetId extends string,
130	  >(
131	    sceneKey: TSceneKey,
132	    progress: number,
133	    sheetId: TSheetId | null,
134	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
135	    isTheatreAuthorMode: boolean,
136	    root?: ParentNode | null,
137	  ): void {
138	    const targetOpacities = new Map<SceneDomTargetKey, number>();
139	    policies.overlays?.forEach((policy) => {
140	      const opacity = this._resolveOverlayOpacity(
141	        sceneKey,
142	        progress,
143	        sheetId,
144	        policy,
145	      );
146	      const nextOpacity = opacity ?? 0;
147	      const previousOpacity = targetOpacities.get(policy.targetKey) ?? 0;
148	      targetOpacities.set(policy.targetKey, Math.max(previousOpacity, nextOpacity));
149	    });
150	
151	    targetOpacities.forEach((opacity, targetKey) => {
152	      this._setOverlayTargetOpacity(
153	        this._resolveDomTarget(policies, targetKey, root),
154	        isTheatreAuthorMode ? 0 : opacity,
155	      );
156	    });
157	  }
158	
159	  private _syncSceneVisibilityPolicies<
160	    TSceneKey extends string,
161	    TSheetId extends string,
162	  >(
163	    sceneKey: TSceneKey,
164	    sheetId: TSheetId | null,
165	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
166	    root?: ParentNode | null,
167	  ): void {
168	    policies.visibility?.forEach((policy) => {
169	      this._applyVisibilityPolicy(sceneKey, sheetId, policies, policy, root);
170	    });
171	  }
172	
173	  private _syncSceneVeilPolicies<
174	    TSceneKey extends string,
175	    TSheetId extends string,
176	  >(
177	    sceneKey: TSceneKey,
178	    progress: number,
179	    sheetId: TSheetId | null,
180	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
181	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
182	  ): void {
183	    policies.veils?.forEach((policy) => {
184	      this._applyVeilPolicy(
185	        sceneKey,
186	        progress,
187	        sheetId,
188	        policy,
189	        resolveTransitionVeil,
190	      );
191	    });
192	  }
193	
194	  private _resetSceneVeilPolicies<
195	    TSceneKey extends string,
196	    TSheetId extends string,
197	  >(
198	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
199	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
200	  ): void {
201	    policies.veils?.forEach((policy) => {
202	      this._setVeilInactive(policy, resolveTransitionVeil);
203	    });
204	  }
205	
206	  private _resetSceneOverlayPolicies<
207	    TSceneKey extends string,
208	    TSheetId extends string,
209	  >(
210	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
211	    root?: ParentNode | null,
212	  ): void {
213	    policies.overlays?.forEach((policy) => {
214	      this._setOverlayTargetOpacity(
215	        this._resolveDomTarget(policies, policy.targetKey, root),
216	        0,
217	      );
218	    });
219	  }
220	
221	  private _resolveOverlayOpacity<
222	    TSceneKey extends string,
223	    TSheetId extends string,
224	  >(
225	    sceneKey: TSceneKey,
226	    progress: number,
227	    sheetId: TSheetId | null,
228	    policy: SceneOverlayPolicy<TSceneKey, TSheetId>,
229	  ): number | null {
230	    for (const window of policy.windows) {
231	      const value = this._resolveTransitionWindowValue(
232	        sceneKey,
233	        progress,
234	        sheetId,
235	        window,
236	      );
237	      if (value == null) continue;
238	      return value;
239	    }
240	    return null;
241	  }
242	
243	  private _applyVisibilityPolicy<
244	    TSceneKey extends string,
245	    TSheetId extends string,
246	  >(
247	    sceneKey: TSceneKey,
248	    sheetId: TSheetId | null,
249	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
250	    policy: SceneVisibilityPolicy<TSceneKey, TSheetId>,
251	    root?: ParentNode | null,
252	  ): void {
253	    const target = this._resolveDomTarget(policies, policy.targetKey, root);
254	    if (!target) return;
255	    const isActive = policy.activeStates.some((state) =>
256	      this._isActiveSceneState(sceneKey, sheetId, state),
257	    );
258	    target.dataset[policy.datasetKey] = isActive ? "true" : "false";
259	  }
260	
261	  private _applyVeilPolicy<
262	    TSceneKey extends string,
263	    TSheetId extends string,
264	  >(
265	    sceneKey: TSceneKey,
266	    progress: number,
267	    sheetId: TSheetId | null,
268	    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
269	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
270	  ): void {
271	    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
272	    if (!reveal) return;
273	
274	    for (const window of policy.windows) {
275	      const veilProgress = this._resolveTransitionWindowValue(
276	        sceneKey,
277	        progress,
278	        sheetId,
279	        window,
280	      );
281	      if (veilProgress == null) continue;
282	      this._sceneTransitionRuntime.syncVeil(reveal, veilProgress);
283	      return;
284	    }
285	
286	    this._sceneTransitionRuntime.resetVeil(
287	      reveal,
288	      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
289	    );
290	  }
291	
292	  private _setVeilInactive<
293	    TSceneKey extends string,
294	    TSheetId extends string,
295	  >(
296	    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
297	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
298	  ): void {
299	    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
300	    if (!reveal) return;
301	    this._sceneTransitionRuntime.resetVeil(
302	      reveal,
303	      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
304	    );
305	  }
306	
307	  private _resolveTransitionVeil(
308	    objectId = sceneTransitionVeil,
309	    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
310	  ): TransitionVeilRuntimePort | null {
311	    return resolveTransitionVeil?.(objectId) ?? null;
312	  }
313	
314	  private _resolveDomTarget<
315	    TSceneKey extends string,
316	    TSheetId extends string,
317	  >(
318	    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
319	    targetKey: SceneDomTargetKey,
320	    root?: ParentNode | null,
321	  ): HTMLElement | null {
322	    if (typeof document === "undefined") return null;
323	    const selector = policies.domTargets?.[targetKey];
324	    if (!selector) return null;
325	    return this._resolveCachedDomTarget(selector, root);
326	  }
327	
328	  private _resolveCachedDomTarget(
329	    selector: string,
330	    root?: ParentNode | null,
331	  ): HTMLElement | null {
332	    const cache = this._resolveDomTargetCache(root);
333	    const cached = cache.get(selector);
334	    if (cached?.isConnected) return cached;
335	    const resolved = (root ?? document).querySelector<HTMLElement>(selector);
336	    cache.set(selector, resolved ?? null);
337	    return resolved;
338	  }
339	
340	  private _resolveDomTargetCache(
341	    root?: ParentNode | null,
342	  ): Map<string, HTMLElement | null> {
343	    if (!root) return this._globalDomTargetCache;
344	    const existing = this._scopedDomTargetCache.get(root);
345	    if (existing) return existing;
346	    const next = new Map<string, HTMLElement | null>();
347	    this._scopedDomTargetCache.set(root, next);
348	    return next;
349	  }
350	
351	  private _setOverlayTargetOpacity(
352	    target: HTMLElement | null,
353	    opacity: number,
354	  ): void {
355	    if (!target) return;
356	    const clampedOpacity = Helpers.clamp01(opacity);
357	    this._applyDomVisibilityState(target, {
358	      visible: clampedOpacity > 0.001,
359	      opacity: clampedOpacity,
360	    });
361	  }
362	
363	  private _isActiveSceneState<
364	    TSceneKey extends string,
365	    TSheetId extends string,
366	  >(
367	    sceneKey: TSceneKey,
368	    sheetId: TSheetId | null,
369	    expectedState: SceneActiveState<TSceneKey, TSheetId>,
370	  ): boolean {
371	    if (sceneKey !== expectedState.sceneKey) return false;
372	    if (sheetId !== expectedState.sheetId) return false;
373	    return true;
374	  }
375	
376	  private _resolveTransitionWindowValue<
377	    TSceneKey extends string,
378	    TSheetId extends string,
379	  >(
380	    sceneKey: TSceneKey | null,
381	    progress: number,
382	    sheetId: TSheetId | null,
383	    window: SceneProgressTransitionWindow<TSceneKey, TSheetId>,
384	  ): number | null {
385	    if (sceneKey !== window.sceneKey) return null;
386	    if (sheetId !== window.sheetId) return null;
387	    const normalizedProgress = Helpers.remap01(
388	      progress,
389	      window.start,
390	      window.end,
391	    );
392	    const easedProgress = this._applyTransitionEase(
393	      normalizedProgress,
394	      window.easing ?? "linear",
395	    );
396	    return Helpers.lerpClamped(window.from, window.to, easedProgress);
397	  }
398	
399	  private _applyTransitionEase(
400	    value: number,
401	    easing: TransitionEaseKey,
402	  ): number {
403	    if (easing === "easeInOutCubic") {
404	      return this._easeInOutCubic(value);
405	    }
406	    return Helpers.clamp01(value);
407	  }
408	
409	  private _easeInOutCubic(value: number): number {
410	    const clampedValue = Helpers.clamp01(value);
411	    if (clampedValue < 0.5) return 4 * clampedValue * clampedValue * clampedValue;
412	    const shiftedValue = -2 * clampedValue + 2;
413	    return 1 - (shiftedValue * shiftedValue * shiftedValue) / 2;
414	  }
415	
416	  private _applyDomVisibilityState(
417	    element: HTMLElement,
418	    state: DomVisibilityState,
419	  ): void {
420	    if (state.opacity != null) {
421	      element.style.opacity = String(Helpers.clamp01(state.opacity));
422	    }
423	    Aria.setVisibility(element, state.visible);
424	  }
425	}
