import { SCENE_TRANSITION_VEIL_SEQUENCE } from "../config/transition.config.js";
import { sceneTransitionVeil } from "../core/setup.js";
import { Aria } from "../utils/Aria.js";
import { Helpers } from "../utils/Helpers.js";
import { SceneTransitionRuntime } from "./SceneTransitionRuntime.js";
import type {
  DomVisibilityState,
  PageSceneRuntimePolicy,
  SceneSyncState,
  SceneActiveState,
  SceneDomTargetKey,
  SceneOverlayPolicy,
  ScenePolicyRuntimeOptions,
  SceneVeilPolicy,
  SceneVisibilityPolicy,
} from "../types/runtime.types.js";
import type {
  SceneProgressTransitionWindow,
  TransitionEaseKey,
  TransitionVeilRuntimePort,
} from "../types/object-runtime.types.js";

export class ScenePolicyRuntime {
  private readonly _globalDomTargetCache = new Map<string, HTMLElement | null>();
  private readonly _scopedDomTargetCache = new WeakMap<
    ParentNode,
    Map<string, HTMLElement | null>
  >();

  constructor(
    private readonly _sceneTransitionRuntime: SceneTransitionRuntime,
  ) {}

  syncScene<TSceneKey extends string, TSheetId extends string>(
    state: SceneSyncState<TSceneKey, TSheetId>,
    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
  ): void {
    this._syncSceneUiState(
      state.sceneKey,
      state.sheetId,
      options.engine,
      options.isTheatreAuthorMode,
      options.sceneSheetEffectRuntime,
    );
    this._syncVisibilityPolicies(state, options);
    options.backgroundController?.sync(
      state.sceneKey,
      state.progress,
      state.sheetId,
      options.backgroundPolicy ?? null,
    );
    this._syncVeilPolicies(state, options);
  }

  resetPolicies<TSceneKey extends string, TSheetId extends string>(
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId> | undefined,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
    root?: ParentNode | null,
  ): void {
    if (!policies) return;
    this._resetSceneOverlayPolicies(policies, root);
    this._resetSceneVeilPolicies(policies, resolveTransitionVeil);
  }

  private _syncSceneUiState<TSceneKey extends string, TSheetId extends string>(
    sceneKey: TSceneKey,
    sheetId: TSheetId | null,
    engine: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>["engine"],
    isTheatreAuthorMode: boolean,
    sceneSheetEffectRuntime: ScenePolicyRuntimeOptions<
      TSceneKey,
      TSheetId
    >["sceneSheetEffectRuntime"],
  ): void {
    if (isTheatreAuthorMode) return;
    sceneSheetEffectRuntime.sync(engine?.getScene() ?? null, sceneKey, sheetId);
  }

  private _syncVisibilityPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    state: { sceneKey: TSceneKey; progress: number; sheetId: TSheetId | null },
    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
  ): void {
    const policies = options.pageRuntimePolicies;
    if (!policies) return;
    this._syncSceneVisibilityPolicies(
      state.sceneKey,
      state.sheetId,
      policies,
      options.root,
    );
    this._syncSceneOverlayPolicies(
      state.sceneKey,
      state.progress,
      state.sheetId,
      policies,
      options.isTheatreAuthorMode,
      options.root,
    );
  }

  private _syncVeilPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    state: { sceneKey: TSceneKey; progress: number; sheetId: TSheetId | null },
    options: ScenePolicyRuntimeOptions<TSceneKey, TSheetId>,
  ): void {
    const policies = options.pageRuntimePolicies;
    if (!policies) return;
    if (options.skipVeilPolicies) return;
    if (options.isTheatreAuthorMode) {
      this._resetSceneVeilPolicies(policies, options.resolveTransitionVeil);
      return;
    }
    this._syncSceneVeilPolicies(
      state.sceneKey,
      state.progress,
      state.sheetId,
      policies,
      options.resolveTransitionVeil,
    );
  }

  private _syncSceneOverlayPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    progress: number,
    sheetId: TSheetId | null,
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    isTheatreAuthorMode: boolean,
    root?: ParentNode | null,
  ): void {
    const targetOpacities = new Map<SceneDomTargetKey, number>();
    policies.overlays?.forEach((policy) => {
      const opacity = this._resolveOverlayOpacity(
        sceneKey,
        progress,
        sheetId,
        policy,
      );
      const nextOpacity = opacity ?? 0;
      const previousOpacity = targetOpacities.get(policy.targetKey) ?? 0;
      targetOpacities.set(policy.targetKey, Math.max(previousOpacity, nextOpacity));
    });

    targetOpacities.forEach((opacity, targetKey) => {
      this._setOverlayTargetOpacity(
        this._resolveDomTarget(policies, targetKey, root),
        isTheatreAuthorMode ? 0 : opacity,
      );
    });
  }

  private _syncSceneVisibilityPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    sheetId: TSheetId | null,
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    root?: ParentNode | null,
  ): void {
    policies.visibility?.forEach((policy) => {
      this._applyVisibilityPolicy(sceneKey, sheetId, policies, policy, root);
    });
  }

  private _syncSceneVeilPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    progress: number,
    sheetId: TSheetId | null,
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
  ): void {
    policies.veils?.forEach((policy) => {
      this._applyVeilPolicy(
        sceneKey,
        progress,
        sheetId,
        policy,
        resolveTransitionVeil,
      );
    });
  }

  private _resetSceneVeilPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
  ): void {
    policies.veils?.forEach((policy) => {
      this._setVeilInactive(policy, resolveTransitionVeil);
    });
  }

  private _resetSceneOverlayPolicies<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    root?: ParentNode | null,
  ): void {
    policies.overlays?.forEach((policy) => {
      this._setOverlayTargetOpacity(
        this._resolveDomTarget(policies, policy.targetKey, root),
        0,
      );
    });
  }

  private _resolveOverlayOpacity<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    progress: number,
    sheetId: TSheetId | null,
    policy: SceneOverlayPolicy<TSceneKey, TSheetId>,
  ): number | null {
    for (const window of policy.windows) {
      const value = this._resolveTransitionWindowValue(
        sceneKey,
        progress,
        sheetId,
        window,
      );
      if (value == null) continue;
      return value;
    }
    return null;
  }

  private _applyVisibilityPolicy<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    sheetId: TSheetId | null,
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    policy: SceneVisibilityPolicy<TSceneKey, TSheetId>,
    root?: ParentNode | null,
  ): void {
    const target = this._resolveDomTarget(policies, policy.targetKey, root);
    if (!target) return;
    const isActive = policy.activeStates.some((state) =>
      this._isActiveSceneState(sceneKey, sheetId, state),
    );
    target.dataset[policy.datasetKey] = isActive ? "true" : "false";
  }

  private _applyVeilPolicy<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    progress: number,
    sheetId: TSheetId | null,
    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
  ): void {
    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
    if (!reveal) return;

    for (const window of policy.windows) {
      const veilProgress = this._resolveTransitionWindowValue(
        sceneKey,
        progress,
        sheetId,
        window,
      );
      if (veilProgress == null) continue;
      this._sceneTransitionRuntime.syncVeil(reveal, veilProgress);
      return;
    }

    this._sceneTransitionRuntime.resetVeil(
      reveal,
      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
    );
  }

  private _setVeilInactive<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    policy: SceneVeilPolicy<TSceneKey, TSheetId>,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
  ): void {
    const reveal = this._resolveTransitionVeil(policy.objectId, resolveTransitionVeil);
    if (!reveal) return;
    this._sceneTransitionRuntime.resetVeil(
      reveal,
      policy.inactiveProgress ?? SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
    );
  }

  private _resolveTransitionVeil(
    objectId = sceneTransitionVeil,
    resolveTransitionVeil?: (objectId?: string) => TransitionVeilRuntimePort | null,
  ): TransitionVeilRuntimePort | null {
    return resolveTransitionVeil?.(objectId) ?? null;
  }

  private _resolveDomTarget<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    policies: PageSceneRuntimePolicy<TSceneKey, TSheetId>,
    targetKey: SceneDomTargetKey,
    root?: ParentNode | null,
  ): HTMLElement | null {
    if (typeof document === "undefined") return null;
    const selector = policies.domTargets?.[targetKey];
    if (!selector) return null;
    return this._resolveCachedDomTarget(selector, root);
  }

  private _resolveCachedDomTarget(
    selector: string,
    root?: ParentNode | null,
  ): HTMLElement | null {
    const cache = this._resolveDomTargetCache(root);
    const cached = cache.get(selector);
    if (cached?.isConnected) return cached;
    const resolved = (root ?? document).querySelector<HTMLElement>(selector);
    cache.set(selector, resolved ?? null);
    return resolved;
  }

  private _resolveDomTargetCache(
    root?: ParentNode | null,
  ): Map<string, HTMLElement | null> {
    if (!root) return this._globalDomTargetCache;
    const existing = this._scopedDomTargetCache.get(root);
    if (existing) return existing;
    const next = new Map<string, HTMLElement | null>();
    this._scopedDomTargetCache.set(root, next);
    return next;
  }

  private _setOverlayTargetOpacity(
    target: HTMLElement | null,
    opacity: number,
  ): void {
    if (!target) return;
    const clampedOpacity = Helpers.clamp01(opacity);
    this._applyDomVisibilityState(target, {
      visible: clampedOpacity > 0.001,
      opacity: clampedOpacity,
    });
  }

  private _isActiveSceneState<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey,
    sheetId: TSheetId | null,
    expectedState: SceneActiveState<TSceneKey, TSheetId>,
  ): boolean {
    if (sceneKey !== expectedState.sceneKey) return false;
    if (sheetId !== expectedState.sheetId) return false;
    return true;
  }

  private _resolveTransitionWindowValue<
    TSceneKey extends string,
    TSheetId extends string,
  >(
    sceneKey: TSceneKey | null,
    progress: number,
    sheetId: TSheetId | null,
    window: SceneProgressTransitionWindow<TSceneKey, TSheetId>,
  ): number | null {
    if (sceneKey !== window.sceneKey) return null;
    if (sheetId !== window.sheetId) return null;
    const normalizedProgress = Helpers.remap01(
      progress,
      window.start,
      window.end,
    );
    const easedProgress = this._applyTransitionEase(
      normalizedProgress,
      window.easing ?? "linear",
    );
    return Helpers.lerpClamped(window.from, window.to, easedProgress);
  }

  private _applyTransitionEase(
    value: number,
    easing: TransitionEaseKey,
  ): number {
    if (easing === "easeInOutCubic") {
      return this._easeInOutCubic(value);
    }
    return Helpers.clamp01(value);
  }

  private _easeInOutCubic(value: number): number {
    const clampedValue = Helpers.clamp01(value);
    if (clampedValue < 0.5) return 4 * clampedValue * clampedValue * clampedValue;
    const shiftedValue = -2 * clampedValue + 2;
    return 1 - (shiftedValue * shiftedValue * shiftedValue) / 2;
  }

  private _applyDomVisibilityState(
    element: HTMLElement,
    state: DomVisibilityState,
  ): void {
    if (state.opacity != null) {
      element.style.opacity = String(Helpers.clamp01(state.opacity));
    }
    Aria.setVisibility(element, state.visible);
  }
}

