120	      plumeNoise * 0.14 +
121	      detailNoise * 0.16 +
122	      bodyNoise * 0.14 +
123	      curlNoise * 0.14 +
124	      grainNoise * 0.08 +
125	      microNoise * 0.12 +
126	      erosionNoise * 0.14 +
127	      (1.0 - distortedUv.y) * 0.24
128	  );
129	  float wispNoise = texture2D(
130	    tPerlin,
131	    flowUv * 0.86 + vec2(0.018 * time, -0.01 * time)
132	  ).r;
