134	    0.24,
135	    0.78,
136	    detailNoise * 0.28 +
137	      bodyNoise * 0.14 +
138	      wispNoise * 0.16 +
139	      curlNoise * 0.18 +
140	      grainNoise * 0.1 +
141	      microNoise * 0.14
142	  );
