323	  private _resolveAboutHeroSloganKeywordStep(
324	    sceneKey: AboutSceneSectionKey,
325	    progress: number,
326	  ): number {
327	    if (sceneKey !== "heroSlogan") return 0;
328	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
329	    const clampedProgress = Helpers.clamp01(progress);
330	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
331	      clampedProgress,
332	    );
333	    return Math.min(
334	      Math.floor(windowedProgress * keywordCount),
335	      keywordCount - 1,
336	    );
337	  }
338	
339	  private _resolveAboutHeroSloganKeywordProgress(progress: number): number {
340	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
341	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
342	    if (end <= start) return progress;
343	    if (progress <= start) return 0;
344	    if (progress >= end) return 1;
345	    return (progress - start) / (end - start);
346	  }
