905	        if (this._contactFlowStage === "success") return;
906	        if (this._contactFlowStage !== "ready") {
907	          throw new Error(
908	            `Invalid contact flow stage for success transition: ${this._contactFlowStage}`,
909	          );
910	        }
911	        this._contactFlowStage = "outtro";
912	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_LEAVING);
913	        await this._wait(CONTACT_THEATRE_DOM_EXIT_DELAY_MS);
914	        await this._playContactTheatreStep(
915	          this._engine,
916	          () => this._pageTheatreBinder.startAfterIntroIfNeeded(this._engine!),
917	        );
918	        this._syncContactSuccessMessage(detail.message);
919	        this._contactFlowStage = "success";
920	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_SUCCESS);
921	      });
922	      detail.resolve();
923	    } catch (error) {
924	      this._contactFlowStage = "ready";
925	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_READY);
926	      detail.reject(error);
