uniform float time;
uniform float progress;
uniform sampler2D texture1;
uniform sampler2D texture2;

varying vec2 vUv;

float easeInOutCubic(float value) {
  if (value < 0.5) {
    return 4.0 * value * value * value;
  }
  float t = -2.0 * value + 2.0;
  return 1.0 - (t * t * t) / 2.0;
}

void main() {
  float blend = easeInOutCubic(clamp(progress, 0.0, 1.0));
  vec4 fromColor = texture2D(texture1, vUv);
  vec4 toColor = texture2D(texture2, vUv);
  gl_FragColor = mix(fromColor, toColor, blend);
}

