uniform float uTime;
uniform vec2 uResolution;

float randomValue(vec2 seed) {
  float value = cos(dot(seed, vec2(21.9898, 78.233))) * 43758.5453;
  return fract(value);
}

float noiseValue(vec2 point) {
  vec2 cell = floor(point);
  vec2 local = fract(point);
  local = local * local * (3.0 - 2.0 * local);

  float a = randomValue(vec2(cell.x, cell.y));
  float b = randomValue(vec2(cell.x + 1.0, cell.y));
  float c = randomValue(vec2(cell.x, cell.y + 1.0));
  float d = randomValue(vec2(cell.x + 1.0, cell.y + 1.0));
  float k0 = a;
  float k1 = b - a;
  float k2 = c - a;
  float k3 = a - b - c + d;
  return k0 + k1 * local.x + k2 * local.y + k3 * local.x * local.y;
}

void main() {
  vec2 safeResolution = max(uResolution, vec2(1.0));
  vec2 fragCoord = gl_FragCoord.xy;
  float time = uTime;

  float color = pow(noiseValue(fragCoord), 40.0) * 20.0;

  float r1 = noiseValue(fragCoord * noiseValue(vec2(sin(time * 0.01))));
  float r2 = noiseValue(
    fragCoord * noiseValue(vec2(cos(time * 0.01), sin(time * 0.01)))
  );
  float r3 = noiseValue(
    fragCoord * noiseValue(vec2(sin(time * 0.05), cos(time * 0.05)))
  );

  vec3 rgb = vec3(color * r1, color * r2, color * r3);
  rgb *= vec3(0.55, 0.7, 1.0);
  gl_FragColor = vec4(rgb, 1.0);
}

