21	float veilFbm(sampler2D textureSampler, vec2 uv) {
22	  float amplitude = 0.5;
23	  float value = 0.0;
24	  vec2 currentUv = uv;
25	  for (int index = 0; index < 4; index += 1) {
26	    value += texture2D(textureSampler, currentUv).r * amplitude;
27	    currentUv *= 2.03;
28	    amplitude *= 0.5;
29	  }
30	  return value;
31	}
32	
33	float veilRidgedNoise(sampler2D textureSampler, vec2 uv) {
34	  float baseValue = veilFbm(textureSampler, uv);
35	  return 1.0 - abs(baseValue * 2.0 - 1.0);
36	}
